spec.probe_patch:
--- a/h11/_writers.py
+++ b/h11/_writers.py
@@ -28,11 +28,11 @@ def write_headers(headers: Headers, write: Writer) -> None:
     raw_items = headers._full_items
     for raw_name, name, value in raw_items:
         if name == b"host":
-            write(b"%s: %s\r\n" % (raw_name, value))
+            write(b"%s: %s\r\n" % (name, value))
     for raw_name, name, value in raw_items:
         if name != b"host":
-            write(b"%s: %s\r\n" % (raw_name, value))
+            write(b"%s: %s\r\n" % (name, value))
     write(b"\r\n")
